import {example,illustrativeAssembly,inputFromRecord,SOURCE,MODEL} from './wheel-limits.js';
import {setupFromRecord} from './footprint.js';
import {probe} from './terrain.js';
const $=id=>document.getElementById(id),form=$('setup');let applied,input=example(),worker,revision=0,dirty=false;
const inputs=r=>({params:r.params,profile:r.profile,assembly:r.assembly,delta:r.delta});
function stop(){revision++;worker?.terminate();worker=null;$('cancel').disabled=true;}
function edits(){stop();dirty=true;$('status').textContent='UNAPPLIED EDITS';$('save').disabled=true;$('scrub').disabled=true;}
function reject(error){edits();$('status').textContent='INPUT REJECTED';$('error').textContent=error.message;}
function fill(a){for(const k of ['centerX','height','radius','rimRadius'])form.elements[k].value=a.params[k];form.elements.dx.value=a.delta[0];form.elements.dz.value=a.delta[1];form.elements.pressure.value=a.assembly.pressure===null?'':a.assembly.pressure/1000;$('setupText').value=JSON.stringify(a,null,2);}
function calculate(a){input=structuredClone(a);stop();const ticket=revision;dirty=true;$('status').textContent='CALCULATING';$('error').textContent='';$('save').disabled=true;$('scrub').disabled=true;$('cancel').disabled=false;worker=new Worker(new URL('./wheel-limits-worker.js',import.meta.url),{type:'module'});
 worker.onerror=()=>{if(ticket===revision)reject(Error('Limit worker failed. Apply again to retry.'));};worker.onmessage=e=>{if(ticket!==revision)return;if(e.data.error){reject(Error(e.data.error));return;}applied=e.data.result;input=inputs(applied);stop();dirty=false;fill(input);$('save').disabled=false;$('scrub').disabled=!applied.sweep;$('scrub').value='0';render();};worker.postMessage(a);
}
const labels={'rim-contact':'RIM CONTACT','domain-boundary':'DOMAIN BOUNDARY','clear':'CLEAR PATH','invalid-start':'INVALID START','initial-rim-overlap':'INITIAL RIM OVERLAP','assembly-rejected':'ASSEMBLY REJECTED'};
function render(){
 const r=applied,s=r.sweep,a=r.assessment;$('status').textContent=labels[r.status];$('fraction').textContent=s?(100*s.fraction).toFixed(2)+'%':'—';$('distance').textContent=s?(s.distance*1000).toFixed(2)+' mm':'—';
 $('reason').textContent=r.reason??(s.status==='clear'?'No rim contact in this prescribed displacement.':s.status==='domain-boundary'?'The tyre envelope reaches the authored domain boundary; terrain is not extrapolated.':s.status==='rim-contact'?'Stop at first rim contact. Impact response, puncture and fracture are not simulated.':'The starting geometry is outside the supported domain; no path advance is admitted.');
 $('staticScope').textContent=r.staticAtStart?`Static starting footprint: ${r.staticAtStart.status}${r.staticAtStart.reason?' — '+r.staticAtStart.reason:''}. No deformed tyre or force is predicted along the approach.`:'No static load prediction is admitted.';
 $('assemblyStatus').textContent=a.status==='unknown'?'UNKNOWN — geometry inspection only':a.status==='incompatible'?'INCOMPATIBLE DECLARATION — approach blocked':'WITHIN DECLARED SERVICE LIMITS — no survival certification';
 $('pressureLimit').textContent=`Inflation: ${r.assembly.pressure===null?'unknown':r.assembly.pressure/1000+' kPa'}. Lowest known maximum: ${a.knownMaximumPa===null?'unknown':a.knownMaximumPa/1000+' kPa'}.`;
 $('issues').replaceChildren();for(const row of [...a.issues,...a.unknown]){const li=document.createElement('li');li.textContent=row.code+': '+row.detail;$('issues').append(li);}
 $('failureModes').replaceChildren();for(const [name,disposition] of [['Rim/ground contact','Continuous geometric boundary; approach stops.'],['Tyre/rim fit and inflation','Declared service limits checked; exact source evidence retained.'],['Bead release / casing rupture','Burst and release criteria unknown; no blowout prediction.'],['Rim yield / fracture','Material/section and local failure envelope unknown.'],['Spoke failure / fatigue','Individual tension, load redistribution and strengths unresolved.'],['Burping / persistent leakage','Seal-gap law and pressure/air-mass evolution unresolved.'],['Suspension / frame damage','Existing rig travel stops remain separate; no strength inferred.']]){const tr=$('failureModes').insertRow();tr.insertCell().textContent=name;tr.insertCell().textContent=disposition;}
 draw();
}
function draw(){if(!applied)return;const canvas=$('rig'),w=canvas.clientWidth,h=canvas.clientHeight;if(w<60||h<60)return;const dpr=devicePixelRatio||1;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);
 const p=applied.params,s=applied.sweep,t=s?Number($('scrub').value)*s.fraction:0,cx=p.centerX+t*applied.delta[0],cz=p.height+t*applied.delta[1],end=s?s.center:[p.centerX,p.height],points=applied.profile.points;
 const xmin=Math.min(p.centerX,end[0])-p.radius-.05,xmax=Math.max(p.centerX,end[0])+p.radius+.05,zmin=Math.min(p.height,end[1])-p.radius-.07,zmax=Math.max(p.height,end[1])+p.radius+.05,scale=Math.min((w-36)/(xmax-xmin),(h-48)/(zmax-zmin)),x=v=>w/2+(v-(xmin+xmax)/2)*scale,z=v=>h/2-(v-(zmin+zmax)/2)*scale;
 c.save();c.beginPath();c.rect(8,24,w-16,h-40);c.clip();c.strokeStyle='#83979d';c.lineWidth=2;c.beginPath();points.forEach((q,i)=>i?c.lineTo(x(q[0]),z(q[1])):c.moveTo(x(q[0]),z(q[1])));c.stroke();
 c.strokeStyle='#64788b';c.setLineDash([5,4]);c.beginPath();c.moveTo(x(p.centerX),z(p.height));c.lineTo(x(end[0]),z(end[1]));c.stroke();c.setLineDash([]);
 for(const [radius,color,dash] of [[p.radius,'#78909d',[4,4]],[p.rimRadius,'#c2a3ff',[]]]){c.strokeStyle=color;c.setLineDash(dash);c.beginPath();c.arc(x(cx),z(cz),radius*scale,0,2*Math.PI);c.stroke();}c.setLineDash([]);
 if(t===0&&applied.staticAtStart?.outline){c.strokeStyle='#70e2ce';c.lineWidth=2;c.beginPath();applied.staticAtStart.outline.forEach((q,i)=>i?c.lineTo(x(q[0]),z(q[1])):c.moveTo(x(q[0]),z(q[1])));c.closePath();c.stroke();}
 const q=probe(applied.profile,{center:[cx,cz],radius:p.rimRadius});$('clearance').textContent=q.status==='available'?(q.gap*1000).toFixed(3)+' mm':'unknown';
 if(s)for(const witness of q.witnesses??[]){const [px,pz]=witness.point;c.fillStyle='#f2b373';c.beginPath();c.arc(x(px),z(pz),4,0,2*Math.PI);c.fill();c.strokeStyle='#f2b373';c.lineWidth=1;c.beginPath();c.moveTo(x(px),z(pz));c.lineTo(x(cx),z(cz));c.stroke();}
 c.fillStyle='#c2a3ff';c.beginPath();c.arc(x(cx),z(cz),3,0,2*Math.PI);c.fill();c.restore();c.fillStyle='#9aabb7';c.font='11px system-ui';c.fillText('x →   z ↑  ·  equal scale  ·  geometry only',10,16);
}
function fromFields(){const a=structuredClone(input),n=k=>form.elements[k].value.trim()?Number(form.elements[k].value):NaN;for(const k of ['centerX','height','radius','rimRadius'])a.params[k]=n(k);a.delta=[n('dx'),n('dz')];const pressure=form.elements.pressure.value.trim()?n('pressure')*1000:null;if(pressure!==a.assembly.pressure){a.assembly.pressure=pressure;a.assembly.sources??={};a.assembly.sources.pressure={kind:'declared',reference:'Viewer pressure entry; kPa converted to Pa.'};}return a;}
form.oninput=edits;form.onsubmit=e=>{e.preventDefault();try{calculate(fromFields());}catch(error){reject(error);}};$('setupText').oninput=edits;$('applyJson').onclick=()=>{try{const text=$('setupText').value;if(new TextEncoder().encode(text).length>2*1024*1024)throw Error('Input exceeds 2 MiB.');calculate(JSON.parse(text));}catch(error){reject(error);}};
$('restore').onclick=()=>{if(!applied)return;stop();dirty=false;input=inputs(applied);fill(input);$('error').textContent='';$('save').disabled=false;$('scrub').disabled=!applied.sweep;render();};$('cancel').onclick=()=>{edits();$('status').textContent='CANCELLED';};$('scrub').oninput=()=>{if(!dirty)draw();};
$('example').onchange=()=>{input=example($('example').value);$('assemblyExample').value='unknown';fill(input);calculate(input);};
$('assemblyExample').onchange=()=>{const a=structuredClone(input),name=$('assemblyExample').value;a.assembly=name==='unknown'?example().assembly:illustrativeAssembly();if(name!=='unknown')a.params.rimRadius=.305;if(name==='overpressure')a.assembly.pressure=260000;if(name==='mismatch')a.assembly.tyreBsd=.622;fill(a);calculate(a);};
$('load').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;edits();const ticket=revision;try{if(file.size>2*1024*1024)throw Error('Record exceeds 2 MiB.');const text=await file.text();if(ticket!==revision)return;const r=JSON.parse(text.replace(/^\uFEFF/,''));if(r.model===MODEL){calculate(inputFromRecord(r));}else{const params=setupFromRecord(r);if(!r.profile)throw Error('Footprint record requires its profile.');calculate({params,profile:r.profile,assembly:example().assembly,delta:[0,-.12]});}}catch(error){if(ticket===revision)reject(error);}};
$('save').onclick=()=>{if(dirty||!applied)return;const url=URL.createObjectURL(new Blob([JSON.stringify(applied,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='bikelab-wheel-limits.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('sourceLink').href=SOURCE.url;
new ResizeObserver(draw).observe($('rig'));window.addEventListener('resize',draw);window.addEventListener('pagehide',()=>{if(worker){edits();$('status').textContent='CANCELLED';}});fill(input);calculate(input);
